/**
 * Identifiers (ADR-0009; data-model.md P1 and §1.6; REQ-RLS-009, NFR-DATA-002). Every primary key is a UUIDv7
 * generated by the application (`uuid` `v7()`: millisecond timestamp, monotonic within one process, 74 random bits),
 * with PostgreSQL 18's `DEFAULT uuidv7()` as the database safety net. Browser-safe (no `node:` import): the web apps
 * use the same helpers for client references.
 */
import { v7 } from 'uuid';

/** Canonical lowercase UUID text with version nibble 7 and the RFC 9562 variant (`10xx`). */
const UUID_V7 = /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

/** A new time-ordered UUIDv7 in canonical lowercase form. */
export function uuidv7(): string {
  return v7();
}

/** True for a canonical lowercase UUIDv7 (the form {@link uuidv7} returns and PostgreSQL prints). */
export function isUuidV7(value: unknown): value is string {
  return typeof value === 'string' && UUID_V7.test(value);
}

/** Milliseconds since the Unix epoch embedded in a UUIDv7 (its first 48 bits); `undefined` for any other value. */
export function uuidV7Timestamp(value: unknown): number | undefined {
  if (!isUuidV7(value)) return undefined;
  return Number.parseInt(value.slice(0, 8) + value.slice(9, 13), 16);
}

/**
 * Reserved actor IDs (data-model §1.6). Both are syntactically valid UUIDv7 (version 7, variant 10, timestamp 0), so
 * the NFR-DATA-002 key test accepts them; both exist as `users` rows (`is_system = true`, no credentials) once the
 * identity module seeds them.
 */
/** `created_by`/`updated_by` and audit `user_id` of seed and system-job writes (REQ-RLS-009, AT-US-064-02). */
export const SYSTEM_ACTOR_ID = '00000000-0000-7000-8000-000000000001';
/** `created_by` of rows written without an authenticated user: guest quotes, anonymous consent (REQ-AUDIT-011). */
export const ANONYMOUS_ACTOR_ID = '00000000-0000-7000-8000-000000000002';
